// Package httpmiddleware defines the middleware the code generated by Blueprint's HTTP plugin
// (plugins/http) installs on its servers and clients.
//
// Tomislav-RetCtx: HTTP's counterpart of gRPC interceptors.  The HTTP plugin does not care what the
// middleware does (tracing, logging, ...); it only passes the instances to the generated server and
// client:
//
//   - server: every method's handler is wrapped as mw(service, method, handler) when the server
//     starts, so the middleware sees each request before the service and the response after it;
//   - client: the client's transport is wrapped as mw(service, transport) when the client is
//     created, so the middleware sees each outgoing request and the response coming back.
//
// Both are the standard net/http hook points (an http.Handler around the handler, an
// http.RoundTripper around the transport).  The names are passed in because, unlike a gRPC
// interceptor, HTTP middleware has no method descriptor: the server is told which method a handler
// serves, and a client's middleware takes the method from the request path ("/<Method>").
package httpmiddleware

import "net/http"

// ServerMiddleware wraps the handler of one method of a service deployed with the HTTP plugin.
// service is the name of the Go interface the server serves, method the method name (the request
// path is "/<method>").  Called once per method when the server starts.
type ServerMiddleware func(service, method string, next http.Handler) http.Handler

// ClientMiddleware wraps the transport of an HTTP client of a service.  service is the name of the
// Go interface the client calls.  Called once when the client is created.
type ClientMiddleware func(service string, next http.RoundTripper) http.RoundTripper

// An ErrorRecorder is a ResponseWriter (provided by a server middleware) that wants the Go error a
// method returned.  An HTTP response only carries a status code and a message; the generated server
// hands the error itself to the middleware with [RecordError] before writing the error response.
type ErrorRecorder interface {
	RecordError(err error)
}

// RecordError gives err to the middleware behind w, if one asked for it (see [ErrorRecorder]).
// Called by the generated server handler when the service returned an error.
func RecordError(w http.ResponseWriter, err error) {
	if r, ok := w.(ErrorRecorder); ok {
		r.RecordError(err)
	}
}
